//! BeeZip's Explorer menu model (docs/M4.md §3), shared by the shell DLL, `shell.plan` and the
//! desktop app: the items, which of them a selection gets, their titles, and the job request a
//! click writes.
//!
//! Nothing here touches the disk. Explorer asks every item for its state on every right-click,
//! so [`menu`] decides from names alone. Paths are Windows paths, but `/` separates them too, so
//! the tests run anywhere.

// Generated by `cargo xtask codegen`, which checks it byte for byte; rustfmt leaves it alone.
#[rustfmt::skip]
mod gen_exts;
mod names;
mod request;

use serde::{Deserialize, Serialize};

pub use names::{archive_stem, file_name, is_archive, volume_key};
pub use request::{JobRequest, REQUEST_VERSION};

/// The longest title the menu shows, in characters. Longer names are cut with an ellipsis.
pub const TITLE_MAX: usize = 40;

/// An item of BeeZip's Explorer menu. The ids are stable: they are config keys
/// (`[shell.items]`), registry values and TypeScript types.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[cfg_attr(
    feature = "wire",
    derive(schemars::JsonSchema, ts_rs::TS, clap::ValueEnum),
    schemars(rename = "MenuItem"),
    ts(rename = "MenuItem")
)]
#[serde(rename_all = "kebab-case")]
pub enum Item {
    /// "Open with BeeZip": each archive in a tab of the main window.
    Open,
    /// "Extract here": into the archive's folder, or into a folder named after it unless
    /// everything is under one top-level folder.
    ExtractHere,
    /// "Extract to "a\"": into a folder named after each archive.
    ExtractFolder,
    /// "Extract to…": the main window's extract dialog.
    ExtractTo,
    /// "Test archive".
    Test,
    /// "Add to "a.zip"", beside the selection.
    AddZip,
    /// "Add to "a.7z"".
    #[serde(rename = "add-7z")]
    #[cfg_attr(feature = "wire", value(name = "add-7z"))]
    Add7z,
    /// "Add to "a.tar.zst"".
    AddTarZst,
    /// "Compress to…": the main window's create dialog, with the selection as its inputs.
    CompressTo,
}

impl Item {
    /// Every item, in menu order: the archive items, then the add items.
    pub const ALL: [Self; 9] = [
        Self::Open,
        Self::ExtractHere,
        Self::ExtractFolder,
        Self::ExtractTo,
        Self::Test,
        Self::AddZip,
        Self::Add7z,
        Self::AddTarZst,
        Self::CompressTo,
    ];

    /// The stable id: `extract-here`, `add-7z`…
    pub const fn id(self) -> &'static str {
        match self {
            Self::Open => "open",
            Self::ExtractHere => "extract-here",
            Self::ExtractFolder => "extract-folder",
            Self::ExtractTo => "extract-to",
            Self::Test => "test",
            Self::AddZip => "add-zip",
            Self::Add7z => "add-7z",
            Self::AddTarZst => "add-tar-zst",
            Self::CompressTo => "compress-to",
        }
    }

    pub fn from_id(id: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|i| i.id() == id)
    }

    /// Offered only when every selected item is an archive. The others are offered for any
    /// files and folders.
    pub const fn for_archives(self) -> bool {
        matches!(
            self,
            Self::Open | Self::ExtractHere | Self::ExtractFolder | Self::ExtractTo | Self::Test
        )
    }

    /// The extension an add item gives its archive: `.zip`, `.7z`, `.tar.zst`.
    pub const fn add_extension(self) -> Option<&'static str> {
        match self {
            Self::AddZip => Some(".zip"),
            Self::Add7z => Some(".7z"),
            Self::AddTarZst => Some(".tar.zst"),
            _ => None,
        }
    }
}

/// One selected item, as Explorer hands it over.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Selected {
    /// Its file-system path. `None` for items that have none (inside a zip folder, on a phone).
    pub path: Option<String>,
    /// A folder rather than a file.
    pub folder: bool,
}

impl Selected {
    pub fn file(path: impl Into<String>) -> Self {
        Self {
            path: Some(path.into()),
            folder: false,
        }
    }

    pub fn folder(path: impl Into<String>) -> Self {
        Self {
            path: Some(path.into()),
            folder: true,
        }
    }
}

/// What the menu takes from the settings (`[shell.items]`, mirrored to the registry for the DLL).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Settings {
    /// Items left out of the menu.
    pub hidden: Vec<Item>,
}

/// A visible menu entry.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub item: Item,
    pub title: String,
    /// A separator goes before it: the first add item, after archive items.
    pub separator_before: bool,
}

/// What a selection is, as far as the menu cares.
struct Kind<'a> {
    paths: Vec<&'a str>,
    /// Every item is a file BeeZip reads.
    archives: bool,
    /// How many archives, counting a volume set once.
    sets: usize,
}

fn kind(selection: &[Selected]) -> Option<Kind<'_>> {
    let paths: Vec<&str> = selection
        .iter()
        .map(|s| s.path.as_deref())
        .collect::<Option<_>>()?;
    if paths.is_empty() {
        return None;
    }
    let archives = selection
        .iter()
        .zip(&paths)
        .all(|(s, p)| !s.folder && is_archive(file_name(p)));
    let sets = if archives {
        let mut keys: Vec<String> = paths.iter().map(|p| volume_key(p)).collect();
        keys.sort_unstable();
        keys.dedup();
        keys.len()
    } else {
        0
    };
    Some(Kind {
        paths,
        archives,
        sets,
    })
}

/// The visible entries for a selection, in order. Empty when BeeZip has nothing to offer: an
/// empty selection, or an item without a file-system path.
pub fn menu(selection: &[Selected], settings: &Settings) -> Vec<Entry> {
    let Some(kind) = kind(selection) else {
        return Vec::new();
    };
    let mut out: Vec<Entry> = Item::ALL
        .into_iter()
        .filter(|i| !settings.hidden.contains(i))
        .filter(|i| kind.archives || !i.for_archives())
        // The extract dialog takes one archive.
        .filter(|i| *i != Item::ExtractTo || kind.sets == 1)
        .map(|item| Entry {
            item,
            title: title_for(item, selection, &kind),
            separator_before: false,
        })
        .collect();
    if let Some(first_add) = out.iter().position(|e| !e.item.for_archives())
        && first_add > 0
    {
        out[first_add].separator_before = true;
    }
    out
}

/// The title an item shows for a selection, at most [`TITLE_MAX`] characters.
pub fn title(item: Item, selection: &[Selected]) -> String {
    match kind(selection) {
        Some(kind) => title_for(item, selection, &kind),
        None => title_for(
            item,
            selection,
            &Kind {
                paths: Vec::new(),
                archives: false,
                sets: 0,
            },
        ),
    }
}

fn title_for(item: Item, selection: &[Selected], kind: &Kind<'_>) -> String {
    match item {
        Item::Open => "Open with BeeZip".into(),
        Item::ExtractHere => "Extract here".into(),
        Item::ExtractFolder => match kind.paths.as_slice() {
            [first, ..] if kind.sets == 1 => {
                quoted("Extract to \"", &archive_stem(file_name(first)), "\\\"")
            }
            _ => "Extract each to its own folder".into(),
        },
        Item::ExtractTo => "Extract to…".into(),
        Item::Test if kind.sets > 1 => "Test archives".into(),
        Item::Test => "Test archive".into(),
        Item::AddZip | Item::Add7z | Item::AddTarZst => {
            let ext = item.add_extension().unwrap_or_default();
            quoted("Add to \"", &add_name(selection), &format!("{ext}\""))
        }
        Item::CompressTo => "Compress to…".into(),
    }
}

/// `prefix + name + suffix`, with the name cut so the whole fits in [`TITLE_MAX`].
fn quoted(prefix: &str, name: &str, suffix: &str) -> String {
    let room = TITLE_MAX.saturating_sub(prefix.chars().count() + suffix.chars().count());
    format!("{prefix}{}{suffix}", cut(name, room))
}

/// `name`, or its first `max - 1` characters and an ellipsis.
fn cut(name: &str, max: usize) -> String {
    if name.chars().count() <= max {
        return name.to_owned();
    }
    let mut s: String = name.chars().take(max.saturating_sub(1)).collect();
    s.push('…');
    s
}

/// The name, without extension, that an add item gives the new archive: one item's own name (a
/// file's without its last extension, an archive's stem), or the folder of several. `archive`
/// when there is none, as for the root of a drive.
pub fn add_name(selection: &[Selected]) -> String {
    let name = match selection {
        [one] => {
            let name = file_name(one.path.as_deref().unwrap_or_default());
            if one.folder || name.is_empty() {
                name.to_owned()
            } else if is_archive(name) {
                archive_stem(name)
            } else {
                match name.rfind('.') {
                    Some(dot) if dot > 0 => name[..dot].to_owned(),
                    _ => name.to_owned(),
                }
            }
        }
        [first, ..] => {
            file_name(names::parent(first.path.as_deref().unwrap_or_default())).to_owned()
        }
        [] => String::new(),
    };
    if name.is_empty() {
        "archive".into()
    } else {
        name
    }
}

